#!/usr/bin/env python3
"""Stage-B inverse from the tuneX Bytecode Bakery write-up."""
def rotr8(x,n): n &= 7; return ((x >> n) | (x << (8-n))) & 0xff
stage2=[(0xaa,0x8b,7,0xdd,0xca,'S'),(0x97,None,3,0xdc,0xc0,'A'),(0x0e,None,6,0x91,0x55,'A'),(0x03,None,5,0xfe,0xff,'A'),(0xbe,None,2,0x1f,0xc1,'A'),(0xea,None,2,0x77,0x3c,'S'),(0x8e,None,4,0x13,0x10,'A'),(0x23,None,5,0x23,0xc1,'S'),(0x76,None,4,0xb8,0xfb,'S'),(0xcf,None,1,0x3d,0x44,'S'),(0xa0,None,7,0xfc,0x62,'S'),(0xe6,None,2,0xf9,0x05,'S'),(0xa5,None,5,0xee,0x22,'A'),(0xf4,None,5,0x8e,0x61,'A'),(0x9a,None,4,0x4c,0x2e,'S'),(0xc0,None,1,0xa2,0x15,'S'),(0x87,None,7,0x24,0x21,'S'),(0x5b,None,2,0x8d,0xfd,'A'),(0xe8,None,2,0x6e,0x80,'A'),(0x20,None,2,0x4a,0xa2,'A'),(0x1f,None,3,0x6b,0x85,'A'),(0xf8,None,1,0x75,0xb0,'S'),(0xca,None,5,0xfd,0x01,'S'),(0x3c,None,5,0x25,0x28,'S'),(0xe5,None,7,0xf3,0x50,'A'),(0x7d,None,7,0x73,0x1f,'S'),(0xa5,None,3,0xf9,0x90,'A'),(0x13,None,5,0x18,0x1d,'A'),(0x12,None,2,0x02,0x8a,'S'),(0x3f,None,4,0xcf,0x47,'S'),(0x34,None,2,0x01,0xc2,'A'),(0x5f,None,1,0xee,0xfa,'S'),(0x99,None,2,0xd4,0xae,'S'),(0x92,None,5,0xef,0xbf,'A'),(0x57,None,5,0xc3,0xc8,'S'),(0x4a,None,3,0xb3,0xb3,'A'),(0xa9,None,6,0x50,0x6f,'S'),(0x21,None,1,0x17,0x4b,'A'),(0x0a,None,5,0xaf,0x54,'A'),(0x79,None,7,0xc2,0x64,'A'),(0x30,None,6,0x9a,0x64,'A'),(0x8c,None,7,0x7e,0x42,'A'),(0x15,None,2,0xb7,0xa5,'S'),(0xfd,None,2,0x7a,0x39,'A'),(0xcc,None,2,0xe3,0xa5,'A'),(0x8c,None,3,0x54,0x52,'A'),(0x7f,None,2,0xd0,0x5d,'S'),(0x92,None,7,0x39,0xb8,'A'),(0xc9,None,2,0x04,0x23,'S'),(0x13,None,1,0xe5,0xc1,'S')]
ing=[]
for i,(k1,k2,n,a,c,op) in enumerate(stage2):
    r=(c-a)&0xff if op=='A' else (c+a)&0xff; value=rotr8(r,n)
    ing.append(value ^ k1 ^ (k2 if i==0 else ing[-1]))
print(bytes(ing))
